 void AddEconomy(C.TabControl tabs,string kind){var p=Stack();var ranking=Grid();var loot=Grid();var summary=new C.TextBlock{TextWrapping=System.Windows.TextWrapping.Wrap};List<EconomyViews.Summary> data=new();double rate=1;string title=kind=="boss"?"Bossing":kind=="heist"?"Heist":"Delve";Label(p,"Native read-only rankings • Chaos per run/hour • complete estimates first. Edit in the existing economy workspace.");
 void Reload(){try{using var doc=JsonDocument.Parse(readSave().GetValueOrDefault("bossledger-v4","{}"));rate=Math.Max(1,EconomyViews.N(doc.RootElement,"rate")??1);data=EconomyViews.Read(doc.RootElement,kind);ranking.ItemsSource=data.Select(x=>new{Strategy=x.Name,Entry=Math.Round(x.Cost,2),Loot=Math.Round(x.Loot,2),Net=Math.Round(x.Net,2),DivinesPerHour=x.Hour.HasValue?Math.Round(x.Hour.Value/rate,2):(double?)null,Missing=x.Missing,Status=x.Invalid?"Invalid pool":x.Missing>0?"Partial":"Populated"}).ToList();summary.Text=data.Count==0?"No saved strategies. Open the full editor to initialize this workspace.":$"{data.Count} strategies • {data.Count(x=>x.Missing==0&&!x.Invalid)} populated estimates";loot.ItemsSource=null;}catch(Exception e){summary.Text=e.Message;}}
 ranking.SelectionChanged+=(_,_)=>{var name=ranking.SelectedItem?.GetType().GetProperty("Strategy")?.GetValue(ranking.SelectedItem)?.ToString();var row=data.FirstOrDefault(x=>x.Name==name);if(row!=null)loot.ItemsSource=EconomyViews.Rows(row.Detail,kind);};
 p.Children.Add(Button("Reload saved data",Reload));p.Children.Add(Button("Open full "+title+" editor",()=>openPage(kind)));p.Children.Add(summary);p.Children.Add(ranking);Label(p,"Selected reward table • expected value before completion multiplier");p.Children.Add(loot);Tab(tabs,title,p);Reload();}


 void AddOverview50(C.TabControl tabs){var p=Stack();var summary=new C.TextBlock{TextWrapping=System.Windows.TextWrapping.Wrap};var grid=Grid();Label(p,"Native economy overview • saved data only");p.Children.Add(summary);p.Children.Add(grid);void Reload(){var rows=store.Rows("SELECT category,count(*) AS items,datetime(max(stamp)/1000,'unixepoch') AS newest_utc FROM market_cache46 WHERE league=$p0 GROUP BY category ORDER BY category",league());Bind(grid,rows);summary.Text=$"League: {league()} • {rows.Sum(r=>Convert.ToInt64(r["items"]))} cached market items."; }p.Children.Add(Button("Refresh saved overview",Reload));p.Children.Add(Button("Open farming rankings",()=>openPage("rank50")));p.Children.Add(Button("Open Bestiary",()=>openPage("beast46")));p.Children.Add(Button("Open net worth",()=>openPage("wallet50")));Tab(tabs,"Economy overview",p);Reload();}
 void AddMarket46(C.TabControl tabs){var p=Stack();var filter=new C.TextBox();var grid=Grid();var summary=new C.TextBlock{TextWrapping=System.Windows.TextWrapping.Wrap};Label(p,"Native shared market catalog • saved quotes only • current league");p.Children.Add(filter);p.Children.Add(summary);p.Children.Add(grid);void Reload(){var rows=store.Rows("SELECT name,category,price AS chaos,source,datetime(stamp/1000,'unixepoch') AS updated_utc FROM market_cache46 WHERE league=$p0 AND name LIKE $p1 ORDER BY name,category LIMIT 1000",league(),"%"+filter.Text+"%");Bind(grid,rows);summary.Text=$"{rows.Count} matching rows (up to 1000). No live requests.";}filter.TextChanged+=(_,_)=>Reload();p.Children.Add(Button("Reload catalog",Reload));Tab(tabs,"Shared market",p);Reload();}
 void RefreshItems()=>Bind(items,store.Rows("SELECT league,boss,kind,name,price,seen FROM item_prices WHERE league=$p0 AND name LIKE $p1 ORDER BY name,boss LIMIT 3000",league(),"%"+search.Text+"%"));
 const string Category39="CASE WHEN lower(area) LIKE '%hideout%' THEN 'Hideout' WHEN lower(area) IN ('rogue harbour','rogue harbor') THEN 'Heist hub' WHEN lower(area) LIKE '%azurite mine%' THEN 'Delve' WHEN lower(area) LIKE '%mine encampment%' THEN 'Delve hub' WHEN lower(area) IN ('the shaper''s realm','the absence of mercy and empathy','the absence of patience and wisdom','the absence of symmetry and harmony','the eye of the storm','the celestial nexus') THEN 'Possible boss area' ELSE 'Unclassified' END";
 void RefreshAreas(){Bind(areas,store.Rows("SELECT area,"+Category39+" AS category,started,ended,round(seconds,1) AS seconds FROM area_sessions ORDER BY id DESC LIMIT 500"));RefreshFarming39();}
 string FarmingFrom39()=>farmingPeriod.SelectedIndex switch{0=>DateTime.Today.ToUniversalTime().ToString("O"),1=>DateTime.UtcNow.AddDays(-7).ToString("O"),2=>DateTime.UtcNow.AddDays(-30).ToString("O"),_=>"0001-01-01"};
 void RefreshFarming39(){var rows=store.Rows("SELECT "+Category39+" AS Activity,count(*) AS Visits,round(sum(seconds)/60.0,2) AS Minutes,round(avg(seconds)/60.0,2) AS AverageMinutes FROM area_sessions WHERE started >= $p0 AND seconds >= 0 GROUP BY 1 ORDER BY sum(seconds) DESC",FarmingFrom39());Bind(farmingSummary,rows);var total=rows.Sum(r=>Convert.ToDouble(r["Minutes"]));var hub=rows.Where(r=>new[]{"Hideout","Heist hub","Delve hub"}.Contains(r["Activity"].ToString())).Sum(r=>Convert.ToDouble(r["Minutes"]));farmingTotals.Text=$"{rows.Sum(r=>Convert.ToInt64(r["Visits"]))} recorded visits • {total/60:0.00} hours • {hub:0.0} hub minutes • {(total>0?100*hub/total:0):0.0}% hub time. Includes unclassified areas and possible idle time.";}
 void ExportFarming39(){var rows=store.Rows("SELECT area,"+Category39+" AS category,started,ended,seconds FROM area_sessions WHERE started >= $p0 ORDER BY id",FarmingFrom39());var dlg=new Microsoft.Win32.SaveFileDialog{Filter="CSV file|*.csv",FileName="poe-ledger-farming.csv"};if(dlg.ShowDialog()!=true)return;string Cell(object v){var s=Convert.ToString(v,System.Globalization.CultureInfo.InvariantCulture)??"";if(s.Length>0&&"=+-@\t\r".Contains(s[0]))s="'"+s;return "\""+s.Replace("\"","\"\"")+"\"";}File.WriteAllLines(dlg.FileName,new[]{"area,category,started,ended,seconds"}.Concat(rows.Select(r=>string.Join(",",new[]{"area","category","started","ended","seconds"}.Select(k=>Cell(r[k]))))));}

 void RefreshAlerts()=>Bind(alerts,store.Rows("SELECT * FROM price_alerts ORDER BY id DESC"));
 void RefreshArt()=>Bind(art,store.Rows("SELECT * FROM artwork ORDER BY kind,name"));
 void ReadClipboard(){try{if(W.Clipboard.ContainsText())clip.Text=W.Clipboard.GetText();CheckClipboard();}catch(Exception e){quote.Text=e.Message;}}
 void CheckClipboard(){var lines=clip.Text.Split('\n').Select(s=>s.Trim()).ToArray();int i=Array.FindIndex(lines,s=>s.StartsWith("Rarity:"));if(i<0||i+1>=lines.Length){quote.Text="No recognized PoE item text.";return;}var name=lines[i+1];if(!lines[i].Contains("Unique")&&!lines[i].Contains("Currency")&&!lines[i].Contains("Gem")){quote.Text="Use the existing Trade importer for non-unique equipment or complex variants.";return;}var rows=store.Rows("SELECT boss,name,price FROM item_prices WHERE league=$p0 AND name=$p1 COLLATE NOCASE",league(),name);quote.Text=rows.Count==0?"No exact saved quote. Use Trade importer for variants.":string.Join("\n",rows.Select(r=>$"{r["name"]} • {r["boss"]}: {r["price"]} c (saved, not live)"));}
 void StartTracking(){if(!File.Exists(logPath.Text))throw new Exception("Choose a valid Client.txt file.");StopTracking();watched=logPath.Text;store.SettingSet("clientlog",watched);offset=new FileInfo(watched).Length;pending="";active=true;areaStatus.Text="Tracking new area transitions.";}
 void EndArea(DateTime? timestamp=null){if(currentArea=="")return;var now=timestamp??DateTime.UtcNow;if(now<started)now=started;store.Exec("INSERT INTO area_sessions(area,started,ended,seconds) VALUES($p0,$p1,$p2,$p3)",currentArea,started.ToString("O"),now.ToString("O"),(now-started).TotalSeconds);currentArea="";RefreshAreas();}
 void StopTracking(){active=false;EndArea();areaStatus.Text="Tracking stopped.";}
 void Tick(){status.Text=market.Status;if(dirty){RefreshItems();dirty=false;}if(active){using var fs=new FileStream(watched,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete);if(fs.Length<offset){offset=0;pending="";EndArea();}fs.Position=offset;using var sr=new StreamReader(fs);pending+=sr.ReadToEnd();offset=fs.Position;var lines=pending.Split('\n');pending=lines[^1];foreach(var line in lines.Take(lines.Length-1)){var m=Regex.Match(line,@"You have entered (.+)\.$");if(!m.Success)m=Regex.Match(line.TrimEnd('\r'),@"You have entered (.+)\.$");if(m.Success){var time=DateTime.UtcNow;if(line.Length>=19&&DateTime.TryParseExact(line.Substring(0,19),"yyyy/MM/dd HH:mm:ss",System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.AssumeLocal,out var parsed))time=parsed.ToUniversalTime();if(currentArea!=""&&time<started)time=started;EndArea(time);currentArea=m.Groups[1].Value.Trim();started=time;}}areaStatus.Text=currentArea==""?"Waiting for area transition.":$"{currentArea} • {(DateTime.UtcNow-started):hh\\:mm\\:ss}";}
 foreach(var a in store.Rows("SELECT * FROM price_alerts WHERE triggered=0")){var matches=store.Rows("SELECT DISTINCT price FROM item_prices WHERE league=$p0 AND name=$p1",a["league"],a["name"]);if(matches.Count!=1)continue;double price=Convert.ToDouble(matches[0]["price"]),t=Convert.ToDouble(a["threshold"]);if(a["direction"].ToString()=="below"?price<=t:price>=t){store.Exec("UPDATE price_alerts SET triggered=1 WHERE id=$p0",a["id"]);notify($"{a["name"]}: saved price {price:0.##} c reached your threshold.");RefreshAlerts();}}}
 void ImportArt(){if(string.IsNullOrWhiteSpace(artName.Text))throw new Exception("Enter exact item or boss name.");var dlg=new Microsoft.Win32.OpenFileDialog{Filter="Images|*.png;*.jpg;*.jpeg;*.webp"};if(dlg.ShowDialog()!=true)return;var info=new FileInfo(dlg.FileName);if(info.Length>8*1024*1024)throw new Exception("Image exceeds 8 MB.");var folder=Path.Combine(Program.DataDir,"artwork");Directory.CreateDirectory(folder);var path=Path.Combine(folder,Guid.NewGuid()+info.Extension);File.Copy(info.FullName,path);store.Exec("INSERT OR REPLACE INTO artwork VALUES($p0,$p1,$p2)",artKind.SelectedItem!.ToString()!,artName.Text.Trim(),path);RefreshArt();artChanged();}
 public void ShowUpdates(){Show();Activate();((C.TabControl)Content).SelectedIndex=6;}
 void DisplayRelease(ReleaseCheck.Release r){bool newer=r.Version>ReleaseCheck.Current;releaseDownload=newer?r.Download:null;availableRelease=newer?r:null;updateResult.Text=$"Installed: {ReleaseCheck.Current} • Available: {r.Version}\n"+(newer?"Update available.":"No newer version listed.")+"\n"+r.Notes+(newer&&r.Download!=null?"\nRelease link: "+r.Download.AbsoluteUri:"");}
 async void CheckRemoteUpdate(){if(updateBusy)return;releaseDownload=null;availableRelease=null;updateBusy=true;updateResult.Text="Checking release manifest…";try{var url=ReleaseCheck.Https(updateUrl.Text).AbsoluteUri;store.SettingSet("updateManifestUrl",url);DisplayRelease(await ReleaseCheck.Fetch(url));}catch(Exception e){updateResult.Text="Update check failed: "+e.Message;}finally{updateBusy=false;}}
 async void InstallUpdate(){if(updateBusy)return;var r=availableRelease;if(r==null||r.Sha256==null||r.Size==null||r.Download==null){updateResult.Text="Check a trusted release manifest with installer checksum and size first.";return;}if(W.MessageBox.Show("Install Poe Ledger "+r.Version+" from "+r.Download.Host+"? Save and close Poe Ledger to continue.","Software update",W.MessageBoxButton.YesNo)!=W.MessageBoxResult.Yes)return;updateBusy=true;using var cts=new CancellationTokenSource(TimeSpan.FromMinutes(20));updateCancel=cts;try{var path=await ReleaseCheck.DownloadInstaller(r,new Progress<int>(n=>updateResult.Text=$"Downloading verified installer: {n}%"),cts.Token);updateResult.Text="Download verified. Preparing database backup…";applyUpdate(path,r.Sha256);}catch(Exception e){updateResult.Text="Update stopped: "+e.Message;}finally{updateCancel=null;updateBusy=false;}}
 void CheckUpdate(){if(updateBusy)return;var dlg=new Microsoft.Win32.OpenFileDialog{Filter="Update manifest|*.json"};if(dlg.ShowDialog()!=true)return;releaseDownload=null;availableRelease=null;DisplayRelease(ReleaseCheck.Parse(File.ReadAllText(dlg.FileName)));}
